  const file = req.body.file;
  const filePath = `/uploads/${file.filename}`;
  fs.writeFile(filePath, file.buffer, (err) => {
    if (err) {
      console.error(err);
      res.status(500).send('Error uploading file');
    } else {
      res.send(`File uploaded successfully: ${filePath}`);
    }
  });
});
```
